先按顺序入队。每轮将队首移到队尾 num 次，再将队首出队淘汰。最后弹出唯一的获胜者。

def hot_potato(name_list, num):
    queue = Queue()
    for name in name_list:
        queue.enqueue(name)
    while queue.size() > 1:
        for _ in range(num):
            queue.enqueue(queue.dequeue())
        queue.dequeue()
    return queue.dequeue()

